-- Event types the caterer offers on the booking form. Run once in the Supabase SQL editor.
create table if not exists "EVENT_TYPE" (
  "EventTypeID" bigint generated by default as identity primary key,
  "Label"       text    not null,
  "IsActive"    boolean not null default true,
  "SortOrder"   integer not null default 0,
  "CreatedAt"   timestamptz not null default now()
);

create unique index if not exists event_type_label_unique on "EVENT_TYPE" (lower("Label"));
alter table "EVENT_TYPE" enable row level security;

insert into "EVENT_TYPE" ("Label", "SortOrder")
select v.label, v.ord
from (values
  ('Wedding', 1), ('Birthday', 2), ('Corporate Event', 3), ('Debut', 4), ('Christening', 5),
  ('Graduation', 6), ('Anniversary', 7), ('Family Gathering', 8), ('Holiday Party', 9)
) as v(label, ord)
where not exists (select 1 from "EVENT_TYPE" e where lower(e."Label") = lower(v.label));
